import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebasNeue = makeLoadFont('BebasNeue');
const loadInter = makeLoadFont('Inter');

// Module-level Google Font loading
const { fontFamily: bebasFamily } = loadBebasNeue();
const { fontFamily: interFamily } = loadInter();

// Schema definition matching Malloy specifications


export type SplitScreenChronologyProps = Record<string, any>;

const SplitScreenChronology: React.FC<SplitScreenChronologyProps> = ({
  backgroundColor = "#030508",
  transparentBackground = false,
  durationInSeconds = 8,
  clockHighlightColor = "#3b82f6",
  splitLineColor = "#475569",
  leftTitle = "ALL NIGHT",
  rightTitle = "6 DAYS A WEEK",
  leftTitleColor = "#ffffff",
  rightTitleColor = "#ffffff",
  calendarAccentColor = "#3b82f6",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const durationInFrames = durationInSeconds * fps;
  const activeStart = 30; // Starts after intro (1s)
  const activeEnd = durationInFrames - 30; // Ends 1s before video finishes
  const spinDuration = activeEnd - activeStart;

  // Background and Intro Animations
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const introSpring = spring({
    frame,
    fps,
    config: { damping: 15, mass: 0.8 },
  });

  const splitLineHeight = interpolate(introSpring, [0, 1], [0, 60]); // Percentage-based
  const splitLineOpacity = interpolate(introSpring, [0, 1], [0, 0.4]);

  const leftTranslateX = interpolate(introSpring, [0, 1], [-100, 0]);
  const leftOpacity = interpolate(introSpring, [0, 1], [0, 1]);

  const rightTranslateX = interpolate(introSpring, [0, 1], [100, 0]);
  const rightOpacity = interpolate(introSpring, [0, 1], [0, 1]);

  // Clock Hand Angle calculations with easing
  const getProgressAtFrame = (f: number) => {
    return interpolate(f, [activeStart, activeEnd], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.25, 0.1, 0.25, 1),
    });
  };

  // Render multiple trails of hands to simulate cinematic motion blur
  const renderClockHandsTrail = () => {
    const trails = [0, 1, 2, 3, 4]; // 5 steps of history for smooth motion blur
    return trails.map((i) => {
      const historicalFrame = Math.max(0, frame - i * 0.4);
      const progress = getProgressAtFrame(historicalFrame);

      // Start at 8:00 PM (20:00 -> 240 degrees)
      // End at 4:00 AM (04:00 -> 480 degrees)
      const hourAngle = 240 + progress * 240;
      // 8 hours means 8 full rotations of the minute hand (8 * 360 = 2880 degrees)
      const minuteAngle = progress * 2880;

      const isMain = i === 0;
      const opacity = isMain ? 1 : 0.35 / i;

      return (
        <g key={i}>
          {/* Hour Hand */}
          <path
            d="M 197 200 L 199 110 L 201 110 L 203 200 Z"
            fill="#f8f9fa"
            transform={`rotate(${hourAngle} 200 200)`}
            opacity={opacity}
          />
          {/* Minute Hand */}
          <path
            d="M 198 200 L 199.5 65 L 200.5 65 L 202 200 Z"
            fill={clockHighlightColor}
            transform={`rotate(${minuteAngle} 200 200)`}
            opacity={opacity}
          />
        </g>
      );
    });
  };

  // Calendar flip configuration
  const days = ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"];
  const columnWidth = 84;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        background: `radial-gradient(circle at 25% 50%, rgba(59, 130, 246, 0.08) 0%, rgba(0,0,0,0) 70%), radial-gradient(circle at 75% 50%, rgba(59, 130, 246, 0.04) 0%, rgba(0,0,0,0) 70%), ${bgColor}`,
        display: "flex",
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "space-between",
        padding: "0 8%",
        color: "#ffffff",
        overflow: "hidden",
      }}
    >
      {/* LEFT COLUMN: Analog Clock */}
      <div
        style={{
          width: "42%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transform: `translateX(${leftTranslateX}px)`,
          opacity: leftOpacity,
          transition: "none",
        }}
      >
        {/* Analog Clock Graphic */}
        <div
          style={{
            position: "relative",
            width: width * 0.22,
            height: width * 0.22,
            maxWidth: 440,
            maxHeight: 440,
            borderRadius: "50%",
            background: "radial-gradient(circle, #0e131f 0%, #05070a 100%)",
            border: `3px solid ${clockHighlightColor}44`,
            boxShadow: `0 0 50px ${clockHighlightColor}22, inset 0 0 30px rgba(0,0,0,0.8)`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          {/* Outer Ring Ambient Glow Highlight */}
          <div
            style={{
              position: "absolute",
              top: -5,
              left: -5,
              right: -5,
              bottom: -5,
              borderRadius: "50%",
              border: "1px solid rgba(255, 255, 255, 0.1)",
              pointerEvents: "none",
            }}
          />

          <svg
            viewBox="0 0 400 400"
            style={{
              width: "100%",
              height: "100%",
              overflow: "visible",
            }}
          >
            {/* Clock Ticks */}
            {Array.from({ length: 12 }).map((_, index) => {
              const angle = (index * 360) / 12;
              const isMajor = index % 3 === 0;
              const tickLength = isMajor ? 18 : 10;
              const strokeWidth = isMajor ? 3 : 1.5;
              const strokeColor = isMajor ? "#64748b" : "#334155";
              return (
                <line
                  key={index}
                  x1={200}
                  y1={200 - 165}
                  x2={200}
                  y2={200 - 165 + tickLength}
                  stroke={strokeColor}
                  strokeWidth={strokeWidth}
                  transform={`rotate(${angle} 200 200)`}
                />
              );
            })}

            {/* Hour Numbers */}
            <text x={200} y={90} fill="#94a3b8" fontSize={26} fontWeight="900" textAnchor="middle" alignmentBaseline="middle" style={{ fontFamily: interFamily }}>12</text>
            <text x={315} y={204} fill="#94a3b8" fontSize={26} fontWeight="900" textAnchor="middle" alignmentBaseline="middle" style={{ fontFamily: interFamily }}>3</text>
            <text x={200} y={320} fill="#94a3b8" fontSize={26} fontWeight="900" textAnchor="middle" alignmentBaseline="middle" style={{ fontFamily: interFamily }}>6</text>
            <text x={85} y={204} fill="#94a3b8" fontSize={26} fontWeight="900" textAnchor="middle" alignmentBaseline="middle" style={{ fontFamily: interFamily }}>9</text>

            {/* Render Hour and Minute Hands with Shutter Motion Blur */}
            {renderClockHandsTrail()}

            {/* Center Cap */}
            <circle cx={200} cy={200} r={8} fill="#ffffff" />
            <circle cx={200} cy={200} r={4} fill="#0f172a" />
          </svg>
        </div>

        {/* Text and Underline Glow */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginTop: 45 }}>
          <h2
            style={{
              fontFamily: bebasFamily,
              fontSize: 85,
              fontWeight: "bold",
              letterSpacing: "4px",
              margin: 0,
              color: leftTitleColor,
              textShadow: "0 0 20px rgba(255,255,255,0.1)",
            }}
          >
            {leftTitle}
          </h2>
          <div
            style={{
              width: 140,
              height: 4,
              borderRadius: 2,
              background: `radial-gradient(circle, ${clockHighlightColor} 0%, rgba(0,0,0,0) 80%)`,
              marginTop: 10,
              boxShadow: `0 0 12px ${clockHighlightColor}`,
            }}
          />
        </div>
      </div>

      {/* CENTER SPLIT SCREEN LINE */}
      <div
        style={{
          width: "2px",
          height: `${splitLineHeight}%`,
          background: `linear-gradient(180deg, rgba(255,255,255,0) 0%, ${splitLineColor}99 30%, ${splitLineColor}99 70%, rgba(255,255,255,0) 100%)`,
          boxShadow: `0 0 10px ${splitLineColor}22`,
          opacity: splitLineOpacity,
          alignSelf: "center",
          transition: "none",
        }}
      />

      {/* RIGHT COLUMN: Modern Desk Calendar */}
      <div
        style={{
          width: "42%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transform: `translateX(${rightTranslateX}px)`,
          opacity: rightOpacity,
          transition: "none",
        }}
      >
        {/* Calendar Card Frame */}
        <div
          style={{
            position: "relative",
            width: "100%",
            maxWidth: 670,
            height: 340,
            background: "linear-gradient(135deg, #0d111a 0%, #07090e 100%)",
            borderRadius: "16px",
            border: "1px solid rgba(255, 255, 255, 0.08)",
            boxShadow: "0 30px 60px rgba(0, 0, 0, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.1)",
            padding: "50px 24px 24px 24px",
            boxSizing: "border-box",
            display: "flex",
            flexDirection: "column",
          }}
        >
          {/* Metal Rings for Desk Calendar Aesthetic */}
          <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 0 }}>
            {days.map((_, i) => {
              const ringX = 24 + i * columnWidth + 30;
              return (
                <svg
                  key={i}
                  width="16"
                  height="36"
                  style={{
                    position: "absolute",
                    left: ringX,
                    top: -18,
                    overflow: "visible",
                  }}
                >
                  <defs>
                    <linearGradient id={`metal-ring-${i}`} x1="0%" y1="0%" x2="100%" y2="100%">
                      <stop offset="0%" stopColor="#94a3b8" />
                      <stop offset="50%" stopColor="#475569" />
                      <stop offset="100%" stopColor="#1e293b" />
                    </linearGradient>
                  </defs>
                  {/* Subtle Ring Cast Shadow */}
                  <path
                    d="M 8 0 C 18 0, 18 36, 8 36 C -2 36, -2 0, 8 0"
                    fill="none"
                    stroke="#000000"
                    strokeWidth="3.5"
                    opacity="0.6"
                    transform="translate(2, 2)"
                  />
                  {/* Metallic Ring */}
                  <path
                    d="M 8 0 C 18 0, 18 36, 8 36 C -2 36, -2 0, 8 0"
                    fill="none"
                    stroke={`url(#metal-ring-${i})`}
                    strokeWidth="3"
                  />
                </svg>
              );
            })}
          </div>

          {/* Days Grid */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              width: "100%",
              height: "100%",
            }}
          >
            {days.map((day, i) => {
              const isSunday = i === 6;

              // Flip Page Spring Timing Offset for each day (Monday -> Saturday)
              // We stagger the activation times across the spinDuration
              const staggerOffset = (spinDuration / 6.2) * i;
              const flipStartFrame = activeStart + staggerOffset;

              const flipSpring = spring({
                frame: frame - flipStartFrame,
                fps,
                config: {
                  damping: 13,
                  mass: 0.55,
                  stiffness: 90,
                },
              });

              // Rotate from perpendicular (-90deg) to flat (0deg) for flip effect
              const rotateX = interpolate(flipSpring, [0, 1], [-90, 0], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });

              // Dynamic shading layer to give 3D paper feel as it curves/flips
              const shadowOpacity = interpolate(flipSpring, [0, 0.5, 1], [0.65, 0.3, 0], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });

              // Background Color interpolates from dark slot backer to bright calendar white (except Sunday)
              const cardBg = isSunday
                ? "#121620"
                : interpolate(flipSpring, [0, 0.7], [0, 1], { extrapolateLeft: "clamp" }) > 0.5
                ? "#f8f9fa"
                : "#121620";

              const textColor = isSunday
                ? "#475569"
                : interpolate(flipSpring, [0, 0.7], [0, 1], { extrapolateLeft: "clamp" }) > 0.5
                ? "#0f172a"
                : "#64748b";

              const labelColor = isSunday
                ? "#475569"
                : interpolate(flipSpring, [0, 0.7], [0, 1], { extrapolateLeft: "clamp" }) > 0.5
                ? "#94a3b8"
                : "#64748b";

              const borderGlow = isSunday
                ? "none"
                : flipSpring > 0.9
                ? `1px solid ${calendarAccentColor}44`
                : "1px solid rgba(255,255,255,0.05)";

              return (
                <div
                  key={day}
                  style={{
                    width: columnWidth,
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                  }}
                >
                  {/* Day Name Label */}
                  <div
                    style={{
                      fontFamily: interFamily,
                      fontSize: 14,
                      fontWeight: "700",
                      letterSpacing: "1px",
                      color: labelColor,
                      marginBottom: 12,
                      textShadow: isSunday ? "none" : `0 0 10px ${calendarAccentColor}11`,
                    }}
                  >
                    {day}
                  </div>

                  {/* Flippable Sheet Calendar Card */}
                  <div
                    style={{
                      position: "relative",
                      width: "100%",
                      height: 180,
                      perspective: "1000px",
                    }}
                  >
                    {/* Underlying Base Slot (Empty Background Card) */}
                    <div
                      style={{
                        position: "absolute",
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        background: "#080a0f",
                        borderRadius: "8px",
                        border: "1px solid rgba(255,255,255,0.02)",
                      }}
                    />

                    {/* Flipping Page */}
                    <div
                      style={{
                        position: "absolute",
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        background: cardBg,
                        borderRadius: "8px",
                        border: borderGlow,
                        boxShadow: isSunday
                          ? "none"
                          : `0 ${interpolate(flipSpring, [0, 1], [2, 12])}px ${interpolate(
                              flipSpring,
                              [0, 1],
                              [4, 24]
                            )}px rgba(0,0,0,0.4)`,
                        transformOrigin: "top center",
                        transform: `rotateX(${isSunday ? 0 : rotateX}deg)`,
                        backfaceVisibility: "hidden",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        overflow: "hidden",
                        transition: "none",
                      }}
                    >
                      {/* Stylized calendar page design (curving bottom edge) */}
                      <div
                        style={{
                          position: "absolute",
                          bottom: 0,
                          left: 0,
                          right: 0,
                          height: "100%",
                          background: isSunday
                            ? "none"
                            : "linear-gradient(180deg, rgba(255,255,255,0) 80%, rgba(0,0,0,0.03) 100%)",
                          pointerEvents: "none",
                        }}
                      />

                      {/* 3D Paper Shadow Overlay */}
                      <div
                        style={{
                          position: "absolute",
                          top: 0,
                          left: 0,
                          right: 0,
                          bottom: 0,
                          background: `linear-gradient(to bottom, rgba(0,0,0,${shadowOpacity}) 0%, rgba(0,0,0,0) 80%)`,
                          pointerEvents: "none",
                        }}
                      />

                      {/* Large Number Graphic representing the flipped day */}
                      <span
                        style={{
                          fontFamily: bebasFamily,
                          fontSize: 54,
                          fontWeight: "bold",
                          color: textColor,
                          userSelect: "none",
                        }}
                      >
                        {i + 1}
                      </span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Text and Underline Glow */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginTop: 45 }}>
          <h2
            style={{
              fontFamily: bebasFamily,
              fontSize: 85,
              fontWeight: "bold",
              letterSpacing: "4px",
              margin: 0,
              color: rightTitleColor,
              textShadow: "0 0 20px rgba(255,255,255,0.1)",
            }}
          >
            {rightTitle}
          </h2>
          <div
            style={{
              width: 140,
              height: 4,
              borderRadius: 2,
              background: `radial-gradient(circle, ${calendarAccentColor} 0%, rgba(0,0,0,0) 80%)`,
              marginTop: 10,
              boxShadow: `0 0 12px ${calendarAccentColor}`,
            }}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SplitScreenChronology;